/bin/bash -lc "node --input-type=module <<'JS'
import { chromium } from '/home/node/.npm/_npx/420ff84f11983ee5/node_modules/playwright/index.mjs';
const browser = await chromium.launch({executablePath:'/home/node/.cache/ms-playwright/chromium-1248/chrome-linux-arm64/chrome', headless: true, args:['--no-sandbox']});
const page = await browser.newPage({viewport:{width:1440,height:1000},deviceScaleFactor:1});
const errors=[];page.on('pageerror',e=>errors.push(e.message));
await page.goto('http://localhost:5173/');
await page.evaluate(()=>document.fonts.ready);
await page.screenshot({path:'/tmp/takt-desktop.png',fullPage:true});
console.log('Desktop:', await page.evaluate(()=>({width:innerWidth,contentWidth:document.documentElement.scrollWidth,height:document.documentElement.scrollHeight,sections:document.querySelectorAll('main > section').length,benefits:document.querySelectorAll('.benefit').length,ctaButtons:document.querySelectorAll('main > section button').length})));
await page.getByRole('button',{name:'Попробовать таймер'}).click();
await page.getByRole('button',{name:'Начать отсчёт'}).click();
await page.waitForTimeout(1250);
if(await page.getByRole('timer').innerText()==='00:00:00')throw Error('Timer did not start');
await page.getByRole('button',{name:'Приостановить'}).click();
const paused=await page.getByRole('timer').innerText();
await page.waitForTimeout(1100);
if(await page.getByRole('timer').innerText()"'!==paused)throw Error('"'Timer did not pause');
await page.getByRole('button',{name:'Продолжить'}).click();
await page.waitForTimeout(1100);
if(await page.getByRole('timer').innerText()===paused)throw Error('Timer did not resume');
await page.getByRole('button',{name:'Сбросить таймер'}).click();
if(await page.getByRole('timer').innerText()"'!=='"'00:00:00')throw Error('Timer did not reset');
await page.keyboard.press('Escape');
if(await page.locator('dialog').isVisible())throw Error('Dialog did not close');
console.log('Timer: start, pause, resume, reset, Escape passed');
for(const width of [320,390,768]){
 await page.setViewportSize({width,height:844});
 const overflow=await page.evaluate(()=>document.documentElement.scrollWidth>innerWidth);
 if(overflow)throw Error('Overflow at '+width);
 if(width===390)await page.screenshot({path:'/tmp/takt-mobile.png',fullPage:true});
 console.log('Responsive width '+width+': no horizontal overflow');
}
console.log('Browser errors:',errors);
await browser.close();
JS"

